\n    total_loss = 0.0\n    num_microbatches = len(microbatches)\n\n    for mb in microbatches:\n        inputs = mb[\"inputs\"]\n        targets = mb[\"targets\"]\n        batch_size = len(inputs)\n\n        # Forward pass, storing activations per layer.\n        activations = [inputs]\n        x = inputs\n        for i in range(L):\n            z = _matmul_T(x, weights[i])\n            bi = biases[i]\n            for r in range(batch_size):\n                zr = z[r]\n                for c in range(len(bi)):\n                    zr[c] += bi[c]\n            if i < L - 1:\n                x = [[math.tanh(v) for v in row] for row in z]\n            else:\n                x = z\n            activations.append(x)\n\n        logits = activations[-1]\n\n        # Softmax cross-entropy loss (mean over the microbatch).\n        probs = []\n        log_probs = []\n        for r in range(batch_size):\n            row = logits[r]\n            m = max(row)\n            shifted = [v - m for v in row]\n            exps = [math.exp(v) for v in shifted]\n            s = sum(exps)\n            pr = [e / s for e in exps]\n            probs.append(pr)\n            log_probs.append([(v - m) - math.log(s) for v in row])\n\n        loss = -sum(log_probs[r][targets[r]] for r in range(batch_size)) / batch_size\n        total_loss += loss\n\n        # Backward pass.\n        dlogits = [row[:] for row in probs]\n        for r in range(batch_size):\n            dlogits[r][targets[r]] -= 1.0\n        inv_batch = 1.0 / batch_size\n        for r in range(batch_size):\n            dr = dlogits[r]\n            for c in range(len(dr)):\n                dr[c] *= inv_batch\n\n        d_activation = dlogits\n        for i in range(L - 1, -1, -1):\n            a_prev = activations[i]\n            # grad_weights[i] += sum_r d_activation[r]^T @ a_prev[r]\n            gw = _outer_sum(d_activation, a_prev)\n            gwi = grad_weights[i]\n            for r in range(len(gw)):\n                for c in range(len(gw[r])):\n                    gwi[r][c] += gw[r][c]\n            # grad_biases[i] += sum over batch\n            gbi = grad_biases[i]\n            for c in range(len(gbi)):\n                s = 0.0\n                for r in range(batch_size):\n                    s += d_activation[r][c]\n                gbi[c] += s\n            if i > 0:\n                # d_z = d_activation @ weights[i]\n                d_z = _matmul(d_activation, weights[i])\n                # derivative of tanh\n                a_i = activations[i]\n                d_activation = [\n                    [d_z[r][c] * (1.0 - a_i[r][c] * a_i[r][c]) for c in range(len(d_z[r]))]\n                    for r in range(batch_size)\n                ]\n\n    loss = total_loss / num_microbatches\n\n    gradients = []\n    for i in range(L):\n        gradients.append({\n            \"weight\": grad_weights[i],\n            \"bias\": grad_biases[i],\n        })\n\n    return {\n        \"loss\": loss,\n        \"gradients\": gradients,\n    }\n", "components/batch_gradients/result.json": "{\"component\": \"batch_gradients\", \"input_sha256\": \"[HASH]\", \"value\": {\"loss\": 0.5652327310620061, \"gradients\": [{\"weight\": [[0.02269765108270621, -0.21339079686248613], [0.007685252261432629, -0.18701102152554488], [0.038289733148732644, 0.16342894231202743]], \"bias\": [-0.026712788534080184, -0.042797252739355494, 0.10888044156328933]}, {\"weight\": [[-0.05297149673545887, 0.14723172869887136, -0.09830699317644373], [0.05297149673545887, -0.14723172869887136, 0.09830699317644373]], \"bias\": [0.08240844483428139, -0.08240844483428136]}]}}"}","content_sha256":"[HASH]","delivery_verified":true,"materialized_files":{"components/batch_gradients/result.json":"[HASH]","components/batch_gradients/work.py":"[HASH]"},"tested_targets":[],"validated":false},{"artifact_id":"artifact-71dea359e36f6ae4","branch_id":"v2-ce7f23259a3a-1","content":"{"components/pipeline_schedule/work.py": "import math\n\n\ndef compute(p